import{_ as t,a as s,b as r}from"./chunks/energy-price.CGaBL0Ht.js";import{_ as n,o as a,c as i,a3 as o}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse(`{"title":"Widgets Énergie","description":"Flux d'énergie, consommation, stockage sur batterie et tarifs : un ensemble de widgets externe pour Home Assistant.","frontmatter":{"title":"Widgets Énergie","description":"Flux d'énergie, consommation, stockage sur batterie et tarifs : un ensemble de widgets externe pour Home Assistant."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/energy.md","filePath":"fr/projects/grafik-visual-studio/energy.md","lastUpdated":1793123188000}`),l={name:"fr/projects/grafik-visual-studio/energy.md"};function u(d,e,c,p,g,m){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="energy-–-widgets" tabindex="-1">Widgets Énergie <a class="header-anchor" href="#energy-–-widgets" aria-label="Permalink to &quot;Widgets Énergie {#energy-–-widgets}&quot;">​</a></h1><p><strong>Energy 0.1.0</strong> est un ensemble externe dédié, conçu pour <strong>Grafik Visual Studio 0.1.255 ou une version ultérieure</strong>. Il ne fait pas partie du pack « Industrial ». La sélection des entités et les valeurs en temps réel fonctionnent aussi bien dans l&#39;éditeur qu&#39;en mode exécution (runtime) ; la sélection de la période temporelle est gérée localement lors de l&#39;exécution, sans écrire d&#39;états dans Home Assistant.</p><h2 id="originalprojekt-und-herkunft" tabindex="-1">Projet original et origine <a class="header-anchor" href="#originalprojekt-und-herkunft" aria-label="Permalink to &quot;Projet original et origine {#originalprojekt-und-herkunft}&quot;">​</a></h2><p>Ce projet s&#39;inspire de <a href="https://github.com/ioBroker/ioBroker.vis-2-widgets-energy" target="_blank" rel="noreferrer">ioBroker.vis-2-widgets-energy</a>, créé par <strong>bluefox / GermanBluefox et ses contributeurs</strong>, et publié sous <strong>licence MIT</strong>. La <a href="https://github.com/ioBroker/ioBroker.vis-2-widgets-energy/tree/main/docs/de" target="_blank" rel="noreferrer">documentation originale</a> décrit la version pour ioBroker. Version du code source vérifiée : <a href="https://github.com/ioBroker/ioBroker.vis-2-widgets-energy/commit/d0a53871ea7e57c5100de2a1f2ef7b2ee82059c7" target="_blank" rel="noreferrer">d0a53871</a>, 7 octobre 2026.</p><p>« Energy » est une <strong>adaptation autonome pour Home Assistant, réalisée par rockbaer2007</strong> ; il ne s&#39;agit ni d&#39;un portage à l&#39;identique, ni d&#39;une publication officielle issue d&#39;ioBroker. Le moteur de rendu, les icônes et l&#39;intégration avec Home Assistant ont été entièrement redéveloppés ; le code source React/vis-2 ainsi que les images originales ne sont pas inclus. Les informations concernant la source et la licence figurent également dans la documentation du paquet.</p><h2 id="bilder" tabindex="-1">Images <a class="header-anchor" href="#bilder" aria-label="Permalink to &quot;Images {#bilder}&quot;">​</a></h2><p>Les images illustrent le mode exécution (runtime) avec des <strong>données de test</strong> ; il ne s&#39;agit pas de mesures en temps réel.</p><p><img src="'+t+'" alt="Flux d&#39;énergie entre le réseau, la maison, le système photovoltaïque, la batterie de stockage et la borne de recharge"></p><table tabindex="0"><thead><tr><th>Batterie de stockage</th><th>Prix dynamique de l&#39;électricité</th></tr></thead><tbody><tr><td><img src="'+s+'" alt="Batterie avec état de charge, puissance et temps restant"></td><td><img src="'+r+'" alt="Prix de l&#39;électricité heure par heure, avec indication des heures les moins chères et les plus chères"></td></tr></tbody></table><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation {#installation}&quot;">​</a></h2><ol><li>Mettez à jour Studio vers la version <strong>0.1.255 ou ultérieure</strong> et rechargez la page avec <strong>Ctrl+F5</strong>.</li><li>Téléchargez <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/raw/master/ha_grafik_visual_studio/packages/energy/ugso.energy.wg" target="_blank" rel="noreferrer">ugso.energy.wg</a>.</li><li>Installez-le via <strong>Paramètres → Packs de widgets → Local</strong>. L&#39;ensemble apparaîtra sous le nom <strong>Energy</strong> dans la palette de widgets.</li><li>Insérez le widget et sélectionnez les sources de mesure via <strong>…</strong> en utilisant le sélecteur d&#39;entités de Home Assistant.</li></ol><p>Le fichier contient huit widgets déclaratifs, des icônes SVG personnalisées pour la palette, ainsi qu&#39;une licence et des instructions. Il ne contient aucun code exécutable. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/energy" target="_blank" rel="noreferrer">Code source et instructions du pack</a>.</p><h2 id="die-acht-widgets" tabindex="-1">Les huit widgets <a class="header-anchor" href="#die-acht-widgets" aria-label="Permalink to &quot;Les huit widgets {#die-acht-widgets}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Widget</th><th>Fonction et sources de mesure</th></tr></thead><tbody><tr><td>Flux d&#39;énergie</td><td>Maison et réseau, plus <strong>1 à 10 nœuds supplémentaires</strong>. Pour chaque nœud : nom, couleur, entité de puissance, multiplicateur, inversion du sens du flux et, en option, une seconde valeur avec unité. Animation des flux désactivable.</td></tr><tr><td>Consommation d&#39;énergie</td><td>Jusqu&#39;à <strong>six séries de données (enregistreurs)</strong>, affichées sous forme de barres ou de lignes ; différences de compteurs ou somme de consommations individuelles ; par heure/jour/mois selon la période choisie.</td></tr><tr><td>Comparaison de consommation</td><td>Valeurs actuelles pour un maximum de <strong>six appareils</strong> ; affichage en barres, lignes ou graphiques circulaires ; paramètres personnalisables (tri, couleur, unité) pour chaque série. Les unités différentes ne sont pas combinées sur un même axe.</td></tr><tr><td>Sélection temporelle</td><td>Jour, semaine, mois ou année ; choix de la date ; navigation (précédent/aujourd&#39;hui/suivant). Un sélecteur peut piloter plusieurs widgets d&#39;historique sur une même page.</td></tr><tr><td>Autarcie et autoconsommation</td><td>Deux anneaux représentant la production, les échanges avec le réseau (import/export) et, en option, la consommation domestique. Si la source « maison » n&#39;est pas définie, le bilan est calculé automatiquement.</td></tr><tr><td>Stockage sur batterie</td><td>État de charge, puissance, capacité, énergie stockée et estimation du temps restant avant charge complète ou décharge totale. Signe configurable pour la charge ; puissance exprimée en W ou kW.</td></tr><tr><td>Coûts de l&#39;énergie</td><td>Consommation × prix d&#39;achat + abonnement (par jour calendaire) − revenus de l&#39;injection ; basé sur les compteurs actuels ou sur une période d&#39;enregistrement. Devise paramétrable.</td></tr><tr><td>Prix dynamique de l&#39;électricité</td><td>Données JSON issues d&#39;un état ou d&#39;un attribut ; affichage par barres horaires ; identification des heures actuelles, les moins chères et les plus chères, ainsi que la moyenne. Les prix négatifs sont pris en compte.</td></tr></tbody></table><h2 id="einheiten-und-unbekannte-werte" tabindex="-1">Unités et valeurs inconnues <a class="header-anchor" href="#einheiten-und-unbekannte-werte" aria-label="Permalink to &quot;Unités et valeurs inconnues {#einheiten-und-unbekannte-werte}&quot;">​</a></h2><p><strong>Les multiplicateurs doivent être configurés explicitement</strong> : p. ex. B. <code>0.001</code> pour Wh → kWh ou W → kW. Un capteur de puissance (W) ne se transforme pas automatiquement en compteur d&#39;énergie (Wh). L&#39;autarcie nécessite des données de même nature et exprimées dans la même unité : soit des puissances, soit des énergies se rapportant à la même période.</p><p>Réseau : valeur positive = prélèvement (achat), valeur négative = injection (vente). Si une source d&#39;injection distincte est configurée, elle remplace la composante négative du réseau. Flux d&#39;énergie : par défaut, les valeurs positives au niveau des nœuds correspondent à un flux vers la maison, et les valeurs négatives à un flux sortant ; pour les consommateurs ou les batteries dont le comptage est inversé, activez l&#39;option <strong>Inverser le sens du flux</strong>.</p><p>En l&#39;absence de source configurée ou valide, le symbole <strong>—</strong> s&#39;affiche. Les valeurs inconnues ne sont pas remplacées par des estimations fictives. Si le dénominateur est égal à 0, les taux restent inconnus. La durée restante est une estimation basée sur la puissance actuelle et la capacité ; il ne s&#39;agit pas d&#39;une prévision générée par l&#39;installation elle-même.</p><h2 id="recorder-und-zeitauswahl" tabindex="-1">Enregistreur (Recorder) et sélecteur de période <a class="header-anchor" href="#recorder-und-zeitauswahl" aria-label="Permalink to &quot;Enregistreur (Recorder) et sélecteur de période {#recorder-und-zeitauswahl}&quot;">​</a></h2><p>Pour afficher l&#39;historique et les coûts passés, Home Assistant doit enregistrer les entités numériques via le composant <strong>Recorder</strong>. Dans le champ <strong>ID du sélecteur de période</strong>, saisissez l&#39;identifiant (ID) du widget de sélection présent sur la même page (par ex. <code>widget-3</code>). Sans cette liaison, la période et la date propres au widget sont utilisées. Si le champ est laissé vide, la date actuelle est prise en compte.</p><p><strong>counter</strong> calcule les différences entre les relevés de compteurs en se basant sur les états conservés par le « recorder ». Les états inconnus ou une réinitialisation du compteur créent une lacune ; les réinitialisations ne sont pas comptabilisées comme de la consommation. <strong>sum</strong> additionne les quantités consommées individuellement et ne convient pas aux compteurs cumulatifs. Les périodes en cours ne contiennent que les données déjà enregistrées ; les segments futurs restent inconnus. Un coût total ne s&#39;affiche que si les données sont complètes et valides pour la partie déjà enregistrée.</p><p>Limites : <strong>366 jours</strong>, <strong>six entités</strong>, <strong>20.000 états par ligne</strong>. Si la réponse est trop volumineuse, elle est interrompue et un message d&#39;avertissement est affiché. Les limites temporelles suivent le fuseau horaire local du navigateur. Certaines périodes anciennes peuvent être absentes en raison de la politique de conservation des données du « recorder ». Cette version n&#39;utilise <strong>pas les statistiques à long terme de HA</strong> (Home Assistant), ni l&#39;historique ioBroker, et ne propose pas d&#39;intégration automatique de la puissance. Les frais fixes s&#39;appliquent à la période calendaire sélectionnée ; en mode « coûts en temps réel », les valeurs des compteurs doivent correspondre à cette période.</p><h2 id="preisdaten" tabindex="-1">Données tarifaires <a class="header-anchor" href="#preisdaten" aria-label="Permalink to &quot;Données tarifaires {#preisdaten}&quot;">​</a></h2><p>Les tableaux (arrays) contenus dans un état ou dans un attribut sélectionné sont pris en charge, y compris lorsqu&#39;ils sont imbriqués dans <code>prices</code>, <code>today</code>, <code>data</code>, <code>values</code> ou <code>result</code>. Les champs temporels sont détectés à partir de <code>startsAt</code>, <code>start_timestamp</code>, <code>start</code>, <code>date</code> et <code>x</code> ; les champs tarifaires, à partir de <code>total</code>, <code>marketprice</code>, <code>price</code>, <code>value</code> et <code>y</code>. Il est possible de saisir d&#39;autres noms. Les horodatages peuvent être au format ISO, en secondes ou en millisecondes. Un tableau de nombres correspond aux heures de la journée locale en cours.</p><p>Définir le facteur de prix par rapport à la source : <strong>100</strong> pour EUR/kWh → ct/kWh, <strong>0.1</strong> pour EUR/MWh → ct/kWh. À partir de maintenant, il est possible de configurer le nombre d&#39;heures, ainsi que les heures « avantageuses » ou « coûteuses » et leurs couleurs respectives.</p><h2 id="unterschiede-zum-original" tabindex="-1">Différences par rapport à l&#39;original <a class="header-anchor" href="#unterschiede-zum-original" aria-label="Permalink to &quot;Différences par rapport à l&#39;original {#unterschiede-zum-original}&quot;">​</a></h2><p>Les huit types de widgets s&#39;inspirent de l&#39;original ; les paramètres et la connectivité ont été adaptés pour Studio et Home Assistant. Cette première version propose une sélection locale de la période temporelle et utilise les états du « Recorder » (historique HA) ; elle ne prend pas en charge les OID ioBroker ni les instances d&#39;historique, n&#39;intègre pas l&#39;ensemble des options de mise en page ou de graphique de vis-2, et ne permet pas l&#39;écriture directe vers les appareils.</p>',27)])])}const v=n(l,[["render",u]]);export{b as __pageData,v as default};
